package com.sporthub.booking;
import static org.assertj.core.api.Assertions.*;
import org.flywaydb.core.Flyway;
import org.junit.jupiter.api.Test;
import java.sql.*;
import java.util.UUID;
class GroupSocialMigrationTest {
 @Test void upgradeCopiesCurrentRosterWithoutInventingAttendanceChatOrKeepDecisions()throws Exception{String url=System.getenv("SPORTHUB_BOOKING_TEST_DB_URL"),user=System.getenv("SPORTHUB_TEST_DB_USER"),password=System.getenv("SPORTHUB_TEST_DB_PASSWORD");org.testcontainers.containers.PostgreSQLContainer<?> pg=null;if(url==null){pg=new org.testcontainers.containers.PostgreSQLContainer<>("postgres:16-alpine");pg.start();url=pg.getJdbcUrl();user=pg.getUsername();password=pg.getPassword();}try{String schema="social_upgrade_"+UUID.randomUUID().toString().replace("-","");Flyway.configure().dataSource(url,user,password).schemas(schema).defaultSchema(schema).target("9").load().migrate();try(var c=DriverManager.getConnection(url,user,password);var s=c.createStatement()){s.execute("SET search_path TO "+schema+",public");s.execute("INSERT INTO slot_reservations(id,court_id,facility_id,holder_id,starts_at,ends_at,expires_at,state,quote) VALUES(gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),NOW()+interval '2 days',NOW()+interval '2 days 1 hour',NOW()+interval '10 minutes','HOLD','{\"marker\":\"original\"}')");s.execute("INSERT INTO bookings(id,reservation_id,facility_id,court_id,created_by,customer_id,current_holder_id,starts_at,ends_at,status,source,amount,currency,price_snapshot,hold_expires_at) SELECT gen_random_uuid(),id,facility_id,court_id,holder_id,holder_id,holder_id,starts_at,ends_at,'PENDING','ONLINE',100,'VND',quote,expires_at FROM slot_reservations");c.setAutoCommit(false);s.execute("INSERT INTO booking_groups(id,owner_id,name,state,deadline,max_members,allocations_locked) SELECT id,current_holder_id,'Legacy','GROUP_PENDING',hold_expires_at,2,false FROM bookings");s.execute("INSERT INTO group_members(id,group_id,user_id,display_name,amount_due,amount_paid,payment_state) SELECT gen_random_uuid(),id,current_holder_id,'Organizer',0,0,'UNPAID' FROM bookings");c.commit();c.setAutoCommit(true);var latest=Flyway.configure().dataSource(url,user,password).schemas(schema).defaultSchema(schema).load();latest.migrate();latest.validate();try(var r=s.executeQuery("SELECT p.state,p.kept_at,p.dissolved_at,b.amount,b.price_snapshot->>'marker',m.user_id=g.owner_id FROM play_groups p JOIN bookings b ON b.id=p.origin_group_id JOIN booking_groups g ON g.id=b.id JOIN play_group_members m ON m.play_group_id=p.id")){r.next();assertThat(r.getString(1)).isEqualTo("OPEN");assertThat(r.getObject(2)).isNull();assertThat(r.getObject(3)).isNull();assertThat(r.getBigDecimal(4)).isEqualByComparingTo("100");assertThat(r.getString(5)).isEqualTo("original");assertThat(r.getBoolean(6)).isTrue();}try(var r=s.executeQuery("SELECT (SELECT count(*) FROM group_member_attendance),(SELECT count(*) FROM play_group_messages),(SELECT count(*) FROM play_group_audit),(SELECT count(*) FROM booking_complaint_cases)")){r.next();for(int i=1;i<=4;i++)assertThat(r.getInt(i)).isZero();}assertThatThrownBy(()->s.execute("UPDATE play_groups SET owner_id=gen_random_uuid()")).isInstanceOf(SQLException.class);}}finally{if(pg!=null)pg.stop();}}
}
